// Appends one line to app/claude-progress.txt with the real clock, so a trace
// stamp can never be typed, counted or back-dated.
//
//   node scripts/trace.mjs <session> "<event>" "<rationale>"
//   node scripts/trace.mjs S2.CODER "feature-3 landed" "the filter reads the spec's window, not a guess"
//
// The first S2 run produced a trace whose every stamp was counter-generated by
// the model: drift grew minutes per feature and both one-way defences appeared
// to postdate the change they defended. Stamping here removes the error class.

import { appendFileSync } from 'node:fs';

const [session, event, rationale] = process.argv.slice(2);
if (!session || !event || !rationale) {
  console.error('usage: node scripts/trace.mjs <session> "<event>" "<rationale>"');
  process.exit(1);
}

const d = new Date();
const pad = (n) => String(n).padStart(2, '0');
const stamp = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
const line = `${stamp}  ${session}  ${event}  RATIONALE: ${rationale}\n`;

appendFileSync('app/claude-progress.txt', line);
process.stdout.write(line);
